import 'reflect-metadata';
import { NestFactory } from '@nestjs/core';
import { ValidationPipe } from '@nestjs/common';
import { AppModule } from './app.module';

async function bootstrap(): Promise<void> {
  const app = await NestFactory.create(AppModule);

  // Apply global validation pipe — strips unknown properties and validates DTOs
  app.useGlobalPipes(
    new ValidationPipe({
      whitelist: true,
      forbidNonWhitelisted: true,
      transform: true,
    }),
  );

  // Allow the Vite dev server to call the API
  app.enableCors({ origin: 'http://localhost:5173', credentials: true });

  await app.listen(3000);
}

bootstrap();

import { Module } from '@nestjs/common';
import { TypeOrmModule } from '@nestjs/typeorm';

/**
 * Root application module.
 *
 * TypeORM is configured here with synchronize: true for local development only.
 * Feature modules (AuthModule, SurveysModule, OrganizationsModule) will be
 * imported here once implemented.
 */
@Module({
  imports: [
    TypeOrmModule.forRoot({
      type: 'postgres',
      host: process.env['DB_HOST'] ?? 'localhost',
      port: parseInt(process.env['DB_PORT'] ?? '5432', 10),
      username: process.env['DB_USER'] ?? 'pulse',
      password: process.env['DB_PASSWORD'] ?? 'pulse',
      database: process.env['DB_NAME'] ?? 'pulse',
      // Entities will be added here as feature modules are built
      entities: [],
      // Auto-create schema in development — will be replaced with migrations
      synchronize: process.env['NODE_ENV'] !== 'production',
      logging: process.env['NODE_ENV'] !== 'production',
    }),
  ],
})
export class AppModule {}

{
  "name": "pulse-surveys-frontend",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "scripts": {
    "dev": "vite",
    "build": "tsc && vite build",
    "preview": "vite preview"
  },
  "dependencies": {
    "react": "19.1.0",
    "react-dom": "19.1.0"
  },
  "devDependencies": {
    "@types/react": "19.1.8",
    "@types/react-dom": "19.1.6",
    "@vitejs/plugin-react": "4.4.1",
    "typescript": "5.8.3",
    "vite": "6.3.5"
  }
}

{
  "compilerOptions": {
    "composite": true,
    "skipLibCheck": true,
    "module": "ESNext",
    "moduleResolution": "bundler",
    "allowSyntheticDefaultImports": true,
    "strict": true
  },
  "include": ["vite.config.ts"]
}

import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

// https://vitejs.dev/config/
export default defineConfig({
  plugins: [react()],
  server: {
    port: 5173,
    proxy: {
      // Proxy API calls to the NestJS backend during development
      '/api': {
        target: 'http://localhost:3000',
        changeOrigin: true,
        rewrite: (path) => path.replace(/^\/api/, ''),
      },
    },
  },
});

import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';

/**
 * Application entry point.
 *
 * Feature screens (LoginScreen, MemberSurveyScreen, ManagerSummaryScreen)
 * will be wired in here once implemented.
 */
function App(): JSX.Element {
  return (
    <div>
      <h1>Pulse Surveys</h1>
      <p>Scaffold only — feature screens coming next.</p>
    </div>
  );
}

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error('Root element #root not found in DOM');
}

createRoot(rootElement).render(
  <StrictMode>
    <App />
  </StrictMode>,
);

