import {
  Column,
  CreateDateColumn,
  Entity,
  OneToMany,
  PrimaryGeneratedColumn,
} from 'typeorm';
import { User } from './user.entity';
import { Survey } from './survey.entity';

@Entity('organizations')
export class Organization {
  @PrimaryGeneratedColumn('uuid')
  id!: string;

  @Column({ type: 'varchar', length: 255, unique: true })
  name!: string;

  @CreateDateColumn({ type: 'timestamptz' })
  createdAt!: Date;

  @OneToMany(() => User, (user) => user.organization)
  users!: User[];

  @OneToMany(() => Survey, (survey) => survey.organization)
  surveys!: Survey[];
}

import {
  Column,
  CreateDateColumn,
  Entity,
  Index,
  JoinColumn,
  ManyToOne,
  OneToMany,
  PrimaryGeneratedColumn,
} from 'typeorm';
import { Organization } from './organization.entity';
import { Response } from './response.entity';

export enum UserRole {
  MANAGER = 'MANAGER',
  MEMBER = 'MEMBER',
}

@Entity('users')
@Index(['organizationId'])
export class User {
  @PrimaryGeneratedColumn('uuid')
  id!: string;

  @Column({ type: 'uuid' })
  organizationId!: string;

  @Column({ type: 'varchar', length: 255 })
  name!: string;

  @Column({ type: 'varchar', length: 255, unique: true })
  email!: string;

  @Column({ type: 'enum', enum: UserRole })
  role!: UserRole;

  @CreateDateColumn({ type: 'timestamptz' })
  createdAt!: Date;

  @ManyToOne(() => Organization, (org) => org.users, { onDelete: 'RESTRICT' })
  @JoinColumn({ name: 'organizationId' })
  organization!: Organization;

  @OneToMany(() => Response, (response) => response.user)
  responses!: Response[];
}

import {
  Column,
  CreateDateColumn,
  Entity,
  Index,
  JoinColumn,
  ManyToOne,
  OneToMany,
  PrimaryGeneratedColumn,
} from 'typeorm';
import { Organization } from './organization.entity';
import { Question } from './question.entity';
import { Response } from './response.entity';

@Entity('surveys')
@Index(['organizationId'])
export class Survey {
  @PrimaryGeneratedColumn('uuid')
  id!: string;

  @Column({ type: 'uuid' })
  organizationId!: string;

  @Column({ type: 'varchar', length: 255 })
  title!: string;

  @CreateDateColumn({ type: 'timestamptz' })
  createdAt!: Date;

  @ManyToOne(() => Organization, (org) => org.surveys, { onDelete: 'RESTRICT' })
  @JoinColumn({ name: 'organizationId' })
  organization!: Organization;

  @OneToMany(() => Question, (question) => question.survey, { cascade: true })
  questions!: Question[];

  @OneToMany(() => Response, (response) => response.survey)
  responses!: Response[];
}

import {
  Column,
  Entity,
  Index,
  JoinColumn,
  ManyToOne,
  OneToMany,
  PrimaryGeneratedColumn,
} from 'typeorm';
import { Survey } from './survey.entity';
import { ResponseAnswer } from './response-answer.entity';

export enum QuestionType {
  RATING = 'RATING',
  YES_NO = 'YES_NO',
}

@Entity('questions')
@Index(['surveyId', 'orderIndex'])
export class Question {
  @PrimaryGeneratedColumn('uuid')
  id!: string;

  @Column({ type: 'uuid' })
  surveyId!: string;

  @Column({ type: 'varchar', length: 1000 })
  text!: string;

  @Column({ type: 'enum', enum: QuestionType })
  type!: QuestionType;

  /**
   * Zero-based display order within the survey (0, 1, 2).
   * Max 3 questions per survey is enforced at the service layer, not here.
   */
  @Column({ type: 'smallint' })
  orderIndex!: number;

  @ManyToOne(() => Survey, (survey) => survey.questions, {
    onDelete: 'CASCADE',
  })
  @JoinColumn({ name: 'surveyId' })
  survey!: Survey;

  @OneToMany(() => ResponseAnswer, (answer) => answer.question)
  answers!: ResponseAnswer[];
}

import {
  Column,
  CreateDateColumn,
  Entity,
  Index,
  JoinColumn,
  ManyToOne,
  OneToMany,
  PrimaryGeneratedColumn,
  Unique,
} from 'typeorm';
import { Survey } from './survey.entity';
import { User } from './user.entity';
import { ResponseAnswer } from './response-answer.entity';

@Entity('responses')
@Unique(['surveyId', 'userId', 'weekKey']) // enforces one submission per member per survey per ISO week
@Index(['surveyId', 'weekKey'])
export class Response {
  @PrimaryGeneratedColumn('uuid')
  id!: string;

  @Column({ type: 'uuid' })
  surveyId!: string;

  @Column({ type: 'uuid' })
  userId!: string;

  /**
   * ISO 8601 week key, e.g. "2026-W38".
   * Computed server-side at submission time — never supplied by the client.
   */
  @Column({ type: 'varchar', length: 8 })
  weekKey!: string;

  @CreateDateColumn({ type: 'timestamptz' })
  createdAt!: Date;

  @ManyToOne(() => Survey, (survey) => survey.responses, {
    onDelete: 'RESTRICT',
  })
  @JoinColumn({ name: 'surveyId' })
  survey!: Survey;

  @ManyToOne(() => User, (user) => user.responses, { onDelete: 'RESTRICT' })
  @JoinColumn({ name: 'userId' })
  user!: User;

  @OneToMany(() => ResponseAnswer, (answer) => answer.response, {
    cascade: true,
  })
  answers!: ResponseAnswer[];
}

import {
  Check,
  Column,
  Entity,
  JoinColumn,
  ManyToOne,
  PrimaryGeneratedColumn,
  Unique,
} from 'typeorm';
import { Response } from './response.entity';
import { Question } from './question.entity';

@Entity('response_answers')
@Unique(['responseId', 'questionId']) // one answer per question per response
@Check('"rating_value" IS NULL OR ("rating_value" >= 1 AND "rating_value" <= 5)')
@Check('NOT ("rating_value" IS NOT NULL AND "yes_no_value" IS NOT NULL)')
export class ResponseAnswer {
  @PrimaryGeneratedColumn('uuid')
  id!: string;

  @Column({ type: 'uuid' })
  responseId!: string;

  @Column({ type: 'uuid' })
  questionId!: string;

  /**
   * Populated when the question type is RATING (1–5).
   * Null for YES_NO questions.
   */
  @Column({ type: 'smallint', nullable: true, name: 'rating_value' })
  ratingValue!: number | null;

  /**
   * Populated when the question type is YES_NO.
   * Null for RATING questions.
   */
  @Column({ type: 'boolean', nullable: true, name: 'yes_no_value' })
  yesNoValue!: boolean | null;

  @ManyToOne(() => Response, (response) => response.answers, {
    onDelete: 'CASCADE',
  })
  @JoinColumn({ name: 'responseId' })
  response!: Response;

  @ManyToOne(() => Question, (question) => question.answers, {
    onDelete: 'RESTRICT',
  })
  @JoinColumn({ name: 'questionId' })
  question!: Question;
}

export { Organization } from './organization.entity';
export { User, UserRole } from './user.entity';
export { Survey } from './survey.entity';
export { Question, QuestionType } from './question.entity';
export { Response } from './response.entity';
export { ResponseAnswer } from './response-answer.entity';

import 'reflect-metadata';
import { DataSource } from 'typeorm';
import { Organization } from './entities/organization.entity';
import { User } from './entities/user.entity';
import { Survey } from './entities/survey.entity';
import { Question } from './entities/question.entity';
import { Response } from './entities/response.entity';
import { ResponseAnswer } from './entities/response-answer.entity';

/**
 * Standalone DataSource used by the TypeORM CLI (migrations:run, migrations:generate, etc.).
 * The NestJS AppModule uses its own TypeOrmModule.forRoot() configuration.
 * Both point at the same database and entity list.
 */
export const AppDataSource = new DataSource({
  type: 'postgres',
  host: process.env['DB_HOST'] ?? 'localhost',
  port: parseInt(process.env['DB_PORT'] ?? '5432', 10),
  username: process.env['DB_USER'] ?? 'pulse',
  password: process.env['DB_PASSWORD'] ?? 'pulse',
  database: process.env['DB_NAME'] ?? 'pulse',
  entities: [Organization, User, Survey, Question, Response, ResponseAnswer],
  migrations: ['src/migrations/*.ts'],
  // synchronize must be false when using migrations
  synchronize: false,
  logging: true,
});

import { MigrationInterface, QueryRunner } from 'typeorm';

/**
 * Initial schema migration — builds all six tables from scratch.
 *
 * Timestamp: 1726790400000  (2026-09-20T00:00:00.000Z, week 2026-W38)
 *
 * Tables created:
 *   organizations, users, surveys, questions, responses, response_answers
 *
 * Key constraints:
 *   - UNIQUE(survey_id, user_id, week_key) on responses
 *   - CHECK(rating_value BETWEEN 1 AND 5) on response_answers
 *   - CHECK(NOT both rating_value and yes_no_value set) on response_answers
 *   - UNIQUE(response_id, question_id) on response_answers
 */
export class InitialSchema1726790400000 implements MigrationInterface {
  name = 'InitialSchema1726790400000';

  public async up(queryRunner: QueryRunner): Promise<void> {
    // ------------------------------------------------------------------
    // 1. organizations
    // ------------------------------------------------------------------
    await queryRunner.query(`
      CREATE TABLE "organizations" (
        "id"         UUID         NOT NULL DEFAULT gen_random_uuid(),
        "name"       VARCHAR(255) NOT NULL,
        "created_at" TIMESTAMPTZ  NOT NULL DEFAULT now(),
        CONSTRAINT "PK_organizations" PRIMARY KEY ("id"),
        CONSTRAINT "UQ_organizations_name" UNIQUE ("name")
      )
    `);

    // ------------------------------------------------------------------
    // 2. users
    // ------------------------------------------------------------------
    await queryRunner.query(`
      CREATE TYPE "users_role_enum" AS ENUM ('MANAGER', 'MEMBER')
    `);

    await queryRunner.query(`
      CREATE TABLE "users" (
        "id"              UUID                 NOT NULL DEFAULT gen_random_uuid(),
        "organization_id" UUID                 NOT NULL,
        "name"            VARCHAR(255)         NOT NULL,
        "email"           VARCHAR(255)         NOT NULL,
        "role"            "users_role_enum"    NOT NULL,
        "created_at"      TIMESTAMPTZ          NOT NULL DEFAULT now(),
        CONSTRAINT "PK_users" PRIMARY KEY ("id"),
        CONSTRAINT "UQ_users_email" UNIQUE ("email"),
        CONSTRAINT "FK_users_organization"
          FOREIGN KEY ("organization_id")
          REFERENCES "organizations"("id")
          ON DELETE RESTRICT
      )
    `);

    await queryRunner.query(`
      CREATE INDEX "IDX_users_organization_id" ON "users" ("organization_id")
    `);

    // ------------------------------------------------------------------
    // 3. surveys
    // ------------------------------------------------------------------
    await queryRunner.query(`
      CREATE TABLE "surveys" (
        "id"              UUID         NOT NULL DEFAULT gen_random_uuid(),
        "organization_id" UUID         NOT NULL,
        "title"           VARCHAR(255) NOT NULL,
        "created_at"      TIMESTAMPTZ  NOT NULL DEFAULT now(),
        CONSTRAINT "PK_surveys" PRIMARY KEY ("id"),
        CONSTRAINT "FK_surveys_organization"
          FOREIGN KEY ("organization_id")
          REFERENCES "organizations"("id")
          ON DELETE RESTRICT
      )
    `);

    await queryRunner.query(`
      CREATE INDEX "IDX_surveys_organization_id" ON "surveys" ("organization_id")
    `);

    // ------------------------------------------------------------------
    // 4. questions
    // ------------------------------------------------------------------
    await queryRunner.query(`
      CREATE TYPE "questions_type_enum" AS ENUM ('RATING', 'YES_NO')
    `);

    await queryRunner.query(`
      CREATE TABLE "questions" (
        "id"          UUID                    NOT NULL DEFAULT gen_random_uuid(),
        "survey_id"   UUID                    NOT NULL,
        "text"        VARCHAR(1000)           NOT NULL,
        "type"        "questions_type_enum"   NOT NULL,
        "order_index" SMALLINT                NOT NULL,
        CONSTRAINT "PK_questions" PRIMARY KEY ("id"),
        CONSTRAINT "FK_questions_survey"
          FOREIGN KEY ("survey_id")
          REFERENCES "surveys"("id")
          ON DELETE CASCADE
      )
    `);

    await queryRunner.query(`
      CREATE INDEX "IDX_questions_survey_order"
        ON "questions" ("survey_id", "order_index")
    `);

    // ------------------------------------------------------------------
    // 5. responses
    // ------------------------------------------------------------------
    await queryRunner.query(`
      CREATE TABLE "responses" (
        "id"         UUID         NOT NULL DEFAULT gen_random_uuid(),
        "survey_id"  UUID         NOT NULL,
        "user_id"    UUID         NOT NULL,
        "week_key"   VARCHAR(8)   NOT NULL,
        "created_at" TIMESTAMPTZ  NOT NULL DEFAULT now(),
        CONSTRAINT "PK_responses" PRIMARY KEY ("id"),
        CONSTRAINT "UQ_responses_survey_user_week"
          UNIQUE ("survey_id", "user_id", "week_key"),
        CONSTRAINT "FK_responses_survey"
          FOREIGN KEY ("survey_id")
          REFERENCES "surveys"("id")
          ON DELETE RESTRICT,
        CONSTRAINT "FK_responses_user"
          FOREIGN KEY ("user_id")
          REFERENCES "users"("id")
          ON DELETE RESTRICT
      )
    `);

    await queryRunner.query(`
      CREATE INDEX "IDX_responses_survey_week"
        ON "responses" ("survey_id", "week_key")
    `);

    // ------------------------------------------------------------------
    // 6. response_answers
    // ------------------------------------------------------------------
    await queryRunner.query(`
      CREATE TABLE "response_answers" (
        "id"           UUID      NOT NULL DEFAULT gen_random_uuid(),
        "response_id"  UUID      NOT NULL,
        "question_id"  UUID      NOT NULL,
        "rating_value" SMALLINT  NULL,
        "yes_no_value" BOOLEAN   NULL,
        CONSTRAINT "PK_response_answers" PRIMARY KEY ("id"),
        CONSTRAINT "UQ_response_answers_response_question"
          UNIQUE ("response_id", "question_id"),
        CONSTRAINT "CHK_response_answers_rating_range"
          CHECK ("rating_value" IS NULL OR ("rating_value" >= 1 AND "rating_value" <= 5)),
        CONSTRAINT "CHK_response_answers_exclusive_value"
          CHECK (NOT ("rating_value" IS NOT NULL AND "yes_no_value" IS NOT NULL)),
        CONSTRAINT "FK_response_answers_response"
          FOREIGN KEY ("response_id")
          REFERENCES "responses"("id")
          ON DELETE CASCADE,
        CONSTRAINT "FK_response_answers_question"
          FOREIGN KEY ("question_id")
          REFERENCES "questions"("id")
          ON DELETE RESTRICT
      )
    `);
  }

  public async down(queryRunner: QueryRunner): Promise<void> {
    await queryRunner.query(`DROP TABLE IF EXISTS "response_answers"`);
    await queryRunner.query(`DROP TABLE IF EXISTS "responses"`);
    await queryRunner.query(`DROP TABLE IF EXISTS "questions"`);
    await queryRunner.query(`DROP TYPE IF EXISTS "questions_type_enum"`);
    await queryRunner.query(`DROP TABLE IF EXISTS "surveys"`);
    await queryRunner.query(`DROP TABLE IF EXISTS "users"`);
    await queryRunner.query(`DROP TYPE IF EXISTS "users_role_enum"`);
    await queryRunner.query(`DROP TABLE IF EXISTS "organizations"`);
  }
}

/**
 * Seed script — inserts demo data for two organizations.
 *
 * Run with:  npm run seed
 *
 * All UUIDs are hardcoded so tests can reference them directly.
 * The script is idempotent: every INSERT uses ON CONFLICT DO NOTHING.
 */

import 'reflect-metadata';
import { AppDataSource } from './data-source';

// ─── Hardcoded UUIDs ────────────────────────────────────────────────────────

export const SEED_IDS = {
  // Organizations
  ORG_ACME:   'aaaaaaaa-0000-0000-0000-000000000001',
  ORG_GLOBEX: 'aaaaaaaa-0000-0000-0000-000000000002',

  // Users — Acme
  USER_ALICE: 'bbbbbbbb-0000-0000-0000-000000000001', // MANAGER
  USER_BOB:   'bbbbbbbb-0000-0000-0000-000000000002', // MEMBER
  USER_CAROL: 'bbbbbbbb-0000-0000-0000-000000000003', // MEMBER

  // Users — Globex
  USER_DAVE:  'bbbbbbbb-0000-0000-0000-000000000004', // MANAGER
  USER_EVE:   'bbbbbbbb-0000-0000-0000-000000000005', // MEMBER
  USER_FRANK: 'bbbbbbbb-0000-0000-0000-000000000006', // MEMBER

  // Surveys
  SURVEY_ACME:   'cccccccc-0000-0000-0000-000000000001',
  SURVEY_GLOBEX: 'cccccccc-0000-0000-0000-000000000002',

  // Questions — Acme survey
  Q_ACME_1: 'dddddddd-0000-0000-0000-000000000001', // RATING
  Q_ACME_2: 'dddddddd-0000-0000-0000-000000000002', // YES_NO
  Q_ACME_3: 'dddddddd-0000-0000-0000-000000000003', // RATING

  // Questions — Globex survey
  Q_GLOBEX_1: 'dddddddd-0000-0000-0000-000000000004', // YES_NO
  Q_GLOBEX_2: 'dddddddd-0000-0000-0000-000000000005', // RATING
} as const;

// ─── Main ────────────────────────────────────────────────────────────────────

async function seed(): Promise<void> {
  await AppDataSource.initialize();
  const runner = AppDataSource.createQueryRunner();

  try {
    await runner.connect();
    await runner.startTransaction();

    // 1. Organizations
    await runner.query(`
      INSERT INTO organizations (id, name)
      VALUES
        ($1, 'Acme'),
        ($2, 'Globex')
      ON CONFLICT (id) DO NOTHING
    `, [SEED_IDS.ORG_ACME, SEED_IDS.ORG_GLOBEX]);

    // 2. Users
    await runner.query(`
      INSERT INTO users (id, organization_id, name, email, role)
      VALUES
        ($1,  $7,  'Alice', 'alice@acme.example',   'MANAGER'),
        ($2,  $7,  'Bob',   'bob@acme.example',     'MEMBER'),
        ($3,  $7,  'Carol', 'carol@acme.example',   'MEMBER'),
        ($4,  $8,  'Dave',  'dave@globex.example',  'MANAGER'),
        ($5,  $8,  'Eve',   'eve@globex.example',   'MEMBER'),
        ($6,  $8,  'Frank', 'frank@globex.example', 'MEMBER')
      ON CONFLICT (id) DO NOTHING
    `, [
      SEED_IDS.USER_ALICE,
      SEED_IDS.USER_BOB,
      SEED_IDS.USER_CAROL,
      SEED_IDS.USER_DAVE,
      SEED_IDS.USER_EVE,
      SEED_IDS.USER_FRANK,
      SEED_IDS.ORG_ACME,
      SEED_IDS.ORG_GLOBEX,
    ]);

    // 3. Surveys — one per org, titled for the current ISO week
    const weekKey = currentISOWeek();
    await runner.query(`
      INSERT INTO surveys (id, organization_id, title)
      VALUES
        ($1, $3, $5),
        ($2, $4, $6)
      ON CONFLICT (id) DO NOTHING
    `, [
      SEED_IDS.SURVEY_ACME,
      SEED_IDS.SURVEY_GLOBEX,
      SEED_IDS.ORG_ACME,
      SEED_IDS.ORG_GLOBEX,
      `Acme Weekly Pulse — ${weekKey}`,
      `Globex Weekly Pulse — ${weekKey}`,
    ]);

    // 4. Questions — Acme survey (3 questions: RATING, YES_NO, RATING)
    await runner.query(`
      INSERT INTO questions (id, survey_id, text, type, order_index)
      VALUES
        ($1, $6, 'How energised do you feel this week? (1 = exhausted, 5 = great)', 'RATING',  0),
        ($2, $6, 'Did you have a 1:1 with your manager this week?',                 'YES_NO',  1),
        ($3, $6, 'How well did your team collaborate this week? (1 = poor, 5 = excellent)', 'RATING', 2),
        ($4, $7, 'Did you feel your work was impactful this week?',                 'YES_NO',  0),
        ($5, $7, 'How clear were your priorities this week? (1 = unclear, 5 = very clear)', 'RATING', 1)
      ON CONFLICT (id) DO NOTHING
    `, [
      SEED_IDS.Q_ACME_1,
      SEED_IDS.Q_ACME_2,
      SEED_IDS.Q_ACME_3,
      SEED_IDS.Q_GLOBEX_1,
      SEED_IDS.Q_GLOBEX_2,
      SEED_IDS.SURVEY_ACME,
      SEED_IDS.SURVEY_GLOBEX,
    ]);

    await runner.commitTransaction();
    console.log(`✓ Seed complete. Surveys tagged with week key: ${weekKey}`);
    console.log('  Organizations:', SEED_IDS.ORG_ACME, '(Acme)', SEED_IDS.ORG_GLOBEX, '(Globex)');
    console.log('  Users seeded: Alice, Bob, Carol (Acme) | Dave, Eve, Frank (Globex)');
  } catch (err) {
    await runner.rollbackTransaction();
    console.error('✗ Seed failed — transaction rolled back:', err);
    process.exit(1);
  } finally {
    await runner.release();
    await AppDataSource.destroy();
  }
}

// ─── ISO week helper ─────────────────────────────────────────────────────────

/**
 * Returns the ISO 8601 week key for the current date, e.g. "2026-W38".
 * ISO weeks start on Monday. Week 1 is the week containing the first Thursday of the year.
 */
export function currentISOWeek(date: Date = new Date()): string {
  // Copy and shift to nearest Thursday to find the correct ISO year+week
  const d = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()));
  // Set to Thursday of the current week (ISO week starts Monday, Thursday is day 4)
  d.setUTCDate(d.getUTCDate() + 4 - (d.getUTCDay() || 7));
  const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
  const weekNum = Math.ceil(
    ((d.getTime() - yearStart.getTime()) / 86_400_000 + 1) / 7,
  );
  return `${d.getUTCFullYear()}-W${String(weekNum).padStart(2, '0')}`;
}

