import { createParamDecorator, ExecutionContext } from '@nestjs/common';
import type { Request } from 'express';
import type { CurrentUser } from './current-user.interface';

/**
 * Parameter decorator that extracts the CurrentUser object from the request.
 *
 * Usage:
 *   @Get('me')
 *   getMe(@CurrentUserParam() user: CurrentUser) { ... }
 *
 * The object is placed on request.user by AuthGuard before this runs.
 */
export const CurrentUserParam = createParamDecorator(
  (_data: unknown, ctx: ExecutionContext): CurrentUser => {
    const request = ctx.switchToHttp().getRequest<Request & { user: CurrentUser }>();
    return request.user;
  },
);

import {
  CanActivate,
  ExecutionContext,
  Injectable,
  UnauthorizedException,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import type { Request } from 'express';
import { Repository } from 'typeorm';
import { User } from '../entities/user.entity';
import type { CurrentUser } from './current-user.interface';

export const AUTH_HEADER = 'x-user-id';

/**
 * Global authentication guard.
 *
 * Reads the X-User-Id header, looks up the user in the database, and
 * attaches CurrentUser to request.user.
 *
 * organizationId is ALWAYS derived from the database record — it is never
 * read from the request body, query string, or any other client-supplied source.
 *
 * Returns HTTP 401 if:
 *   - The X-User-Id header is absent or empty.
 *   - No user record exists for the supplied ID.
 */
@Injectable()
export class AuthGuard implements CanActivate {
  constructor(
    @InjectRepository(User)
    private readonly userRepository: Repository<User>,
  ) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const request = context.switchToHttp().getRequest<Request & { user: CurrentUser }>();

    const userId = request.headers[AUTH_HEADER];

    if (!userId || typeof userId !== 'string' || userId.trim() === '') {
      throw new UnauthorizedException('X-User-Id header is required');
    }

    // Always load from DB — organizationId and role come from the database only
    const user = await this.userRepository.findOne({
      where: { id: userId.trim() },
      select: ['id', 'organizationId', 'role', 'name'],
    });

    if (!user) {
      throw new UnauthorizedException('User not found');
    }

    request.user = {
      id: user.id,
      organizationId: user.organizationId,
      role: user.role,
      name: user.name,
    };

    return true;
  }
}

