@Controller('auth')
export class AuthController {
  constructor(private readonly authService: AuthService) {}

  /**
   * GET /auth/me
   *
   * Returns the resolved identity for the caller.
   * Used by the React app immediately after login to determine which
   * screen to render (manager summary vs member survey).
   *
   * Protected by the global AuthGuard — requires X-User-Id header.
   */
  @Get('me')
  getMe(@CurrentUserParam() currentUser: CurrentUser) {
    return this.authService.getMe(currentUser);
  }

  /**
   * GET /auth/users
   *
   * Returns all seeded users for the login dropdown.
   * Intentionally unauthenticated — no X-User-Id needed.
   *
   * The global guard is bypassed by the IS_PUBLIC_KEY metadata set in
   * AuthModule; see auth.guard.ts for how PUBLIC routes are skipped.
   */
  @Get('users')
  getUsers() {
    return this.authService.getAllUsers();
  }
}

import { Injectable } from '@nestjs/common';
