    @InjectRepository(Question)
    private readonly questionRepository: Repository<Question>,
    @InjectRepository(Response)
    private readonly responseRepository: Repository<Response>,
    private readonly dataSource: DataSource,
  ) {}

  // ─── Survey creation ───────────────────────────────────────────────────────

  /**
   * Create a survey with its questions for the given organization.
   * orderIndex is assigned server-side (0-based, matching the array order).
   * organizationId comes exclusively from the caller — never from the DTO.
   */
  async createSurvey(dto: CreateSurveyDto, organizationId: string): Promise<Survey> {
    const survey = this.surveyRepository.create({
      title: dto.title,
      organizationId,
      questions: dto.questions.map((q, index) => ({
        text: q.text,
        type: q.type,
        orderIndex: index,
      })),
    });

    return this.surveyRepository.save(survey);
  }

  // ─── Survey retrieval ──────────────────────────────────────────────────────

  /**
   * Return the most recently created survey for the organization.
   * "Active" is not a status flag — the newest survey is always returned.
   */
  async getActiveSurvey(organizationId: string): Promise<Survey> {
    const survey = await this.surveyRepository.findOne({
      where: { organizationId },
      relations: { questions: true },
      order: { createdAt: 'DESC' },
    });

    if (!survey) {
      throw new NotFoundException('No active survey found for your organization');
    }

    survey.questions.sort((a, b) => a.orderIndex - b.orderIndex);
    return survey;
  }

  /**
   * Return a survey by id, scoped to organizationId.
   * Returns 404 on cross-org access to avoid leaking resource existence.
   */
  async getSurveyById(id: string, organizationId: string): Promise<Survey> {
    const survey = await this.surveyRepository.findOne({
      where: { id, organizationId },
      relations: { questions: true },
    });

    if (!survey) {
      throw new NotFoundException('Survey not found');
    }

    survey.questions.sort((a, b) => a.orderIndex - b.orderIndex);
    return survey;
  }

  // ─── Response submission ───────────────────────────────────────────────────

  /**
   * Submit a response for a survey.
   *
   * Validation order (fail-fast, cheapest checks first):
   *   1. Survey exists and belongs to caller's org (404 if not).
   *   2. All survey questions are answered — no extras, no missing (422).
   *   3. Each answer's questionId belongs to the survey (422).
   *   4. Each answer value matches the question's type (422).
   *   5. Duplicate submission check: existing row for (survey, user, week) → 409.
   *   6. Insert response + answers in a transaction.
   *      DB UNIQUE constraint is the final safety net; catch it → 409.
   */
  async submitResponse(
    surveyId: string,
    organizationId: string,
    userId: string,
    dto: SubmitResponseDto,
  ): Promise<SubmitResponseResult> {
    // ── 1. Load survey with questions, scoped to org ──────────────────────
    const survey = await this.surveyRepository.findOne({
      where: { id: surveyId, organizationId },
      relations: { questions: true },
    });

    if (!survey) {
      throw new NotFoundException('Survey not found');
    }

    const questions = survey.questions;
    const questionMap = new Map(questions.map((q) => [q.id, q]));

    // ── 2 & 3. Check every survey question is answered, no extras ────────
    const answeredIds = new Set(dto.answers.map((a) => a.questionId));

    // Extra answers for questions not in this survey
    for (const a of dto.answers) {
      if (!questionMap.has(a.questionId)) {
        throw new UnprocessableEntityException(
          `Question ${a.questionId} does not belong to this survey`,
        );
      }
    }

    // Missing answers for survey questions
    for (const q of questions) {
      if (!answeredIds.has(q.id)) {
        throw new UnprocessableEntityException(
          `Missing answer for question ${q.id}`,
        );
      }
    }

    // Duplicate answer for the same question
    if (answeredIds.size !== dto.answers.length) {
      throw new UnprocessableEntityException('Duplicate answers for the same question');
    }

    // ── 4. Type validation for each answer ────────────────────────────────
    for (const a of dto.answers) {
      const question = questionMap.get(a.questionId)!;
      this.validateAnswerType(question, a);
    }

    // ── 5. Service-layer duplicate check (returns clean 409 before DB) ────
    const weekKey = currentISOWeek();
    const existing = await this.responseRepository.findOne({
      where: { surveyId, userId, weekKey },
      select: { id: true },
    });

    if (existing) {
      throw new ConflictException(
        'You have already submitted a response for this survey this week.',
      );
    }

    // ── 6. Persist in a transaction ───────────────────────────────────────
    try {
      return await this.dataSource.transaction(async (manager) => {
        const response = manager.create(Response, {
          surveyId,
          userId,
          weekKey,
        });
        const savedResponse = await manager.save(Response, response);

        const answerEntities = dto.answers.map((a) => {
          const question = questionMap.get(a.questionId)!;
          return manager.create(ResponseAnswer, {
            responseId: savedResponse.id,
            questionId: a.questionId,
            ratingValue: question.type === QuestionType.RATING ? (a.ratingValue ?? null) : null,
            yesNoValue: question.type === QuestionType.YES_NO ? (a.yesNoValue ?? null) : null,
          });
        });

        await manager.save(ResponseAnswer, answerEntities);

        return {
          id: savedResponse.id,
          surveyId: savedResponse.surveyId,
          userId: savedResponse.userId,
          weekKey: savedResponse.weekKey,
          createdAt: savedResponse.createdAt,
        };
      });
    } catch (err: unknown) {
      // Catch DB unique constraint violation on (survey_id, user_id, week_key)
      if (this.isUniqueViolation(err)) {
        throw new ConflictException(
          'You have already submitted a response for this survey this week.',
        );
      }
      throw err;
    }
  }

  // ─── Private helpers ───────────────────────────────────────────────────────

  private validateAnswerType(question: Question, answer: {
    questionId: string;
    ratingValue?: number;
    yesNoValue?: boolean;
  }): void {
    if (question.type === QuestionType.RATING) {
      if (answer.yesNoValue !== undefined && answer.yesNoValue !== null) {
        throw new UnprocessableEntityException(
          `Question ${question.id} is a RATING question — use ratingValue, not yesNoValue`,
        );
      }
      if (answer.ratingValue === undefined || answer.ratingValue === null) {
        throw new UnprocessableEntityException(
          `Question ${question.id} is a RATING question — ratingValue is required`,
        );
      }
    }

    if (question.type === QuestionType.YES_NO) {
      if (answer.ratingValue !== undefined && answer.ratingValue !== null) {
        throw new UnprocessableEntityException(
          `Question ${question.id} is a YES_NO question — use yesNoValue, not ratingValue`,
        );
      }
      if (answer.yesNoValue === undefined || answer.yesNoValue === null) {
        throw new UnprocessableEntityException(
          `Question ${question.id} is a YES_NO question — yesNoValue is required`,
        );
      }
    }
  }

  /**
   * Detect a PostgreSQL unique-constraint violation.
   * pg driver surfaces this as error code '23505'.
   */
  private isUniqueViolation(err: unknown): boolean {
    return (
      typeof err === 'object' &&
      err !== null &&
      'code' in err &&
      (err as { code: string }).code === '23505'
    );
  }
}

import {
  Body,
  Controller,
  Get,
  HttpCode,
  HttpStatus,
  Param,
  Post,
} from '@nestjs/common';
import { CurrentUserParam } from '../auth/current-user.decorator';
import type { CurrentUser } from '../auth/current-user.interface';
import { Roles } from '../auth/roles.decorator';
import { UserRole } from '../entities/user.entity';
import { CreateSurveyDto } from './dto/create-survey.dto';
import { SubmitResponseDto } from './dto/submit-response.dto';
import { SurveysService } from './surveys.service';

/**
 * SurveysController — thin HTTP layer.
 * All business logic lives in SurveysService.
 */
@Controller('surveys')
export class SurveysController {
  constructor(private readonly surveysService: SurveysService) {}

  /**
   * POST /surveys
   * MANAGER only. organizationId is taken from currentUser — never from the body.
   */
  @Post()
  @HttpCode(HttpStatus.CREATED)
  @Roles(UserRole.MANAGER)
  createSurvey(
    @Body() dto: CreateSurveyDto,
    @CurrentUserParam() currentUser: CurrentUser,
  ) {
    return this.surveysService.createSurvey(dto, currentUser.organizationId);
  }

  /**
   * GET /surveys/active
   * MANAGER or MEMBER. Returns the most recently created survey for the caller's org.
   * Declared before /:id to avoid being matched by the param route.
   */
  @Get('active')
  getActiveSurvey(@CurrentUserParam() currentUser: CurrentUser) {
    return this.surveysService.getActiveSurvey(currentUser.organizationId);
  }

  /**
   * POST /surveys/:id/responses
   * MEMBER only. weekKey computed server-side; never read from the request.
   */
  @Post(':id/responses')
  @HttpCode(HttpStatus.CREATED)
  @Roles(UserRole.MEMBER)
  submitResponse(
    @Param('id') surveyId: string,
    @Body() dto: SubmitResponseDto,
    @CurrentUserParam() currentUser: CurrentUser,
  ) {
    return this.surveysService.submitResponse(
      surveyId,
      currentUser.organizationId,
      currentUser.id,
      dto,
    );
  }

  /**
   * GET /surveys/:id
   * MANAGER or MEMBER. Returns 404 if the survey belongs to a different org.
   */
  @Get(':id')
  getSurveyById(
    @Param('id') id: string,
    @CurrentUserParam() currentUser: CurrentUser,
  ) {
    return this.surveysService.getSurveyById(id, currentUser.organizationId);
  }
}

import { Module } from '@nestjs/common';
import { TypeOrmModule } from '@nestjs/typeorm';
import { Question } from '../entities/question.entity';
import { ResponseAnswer } from '../entities/response-answer.entity';
import { Response } from '../entities/response.entity';
import { Survey } from '../entities/survey.entity';
import { SurveysController } from './surveys.controller';
import { SurveysService } from './surveys.service';

@Module({
  imports: [TypeOrmModule.forFeature([Survey, Question, Response, ResponseAnswer])],
  controllers: [SurveysController],
  providers: [SurveysService],
  exports: [SurveysService],
})
export class SurveysModule {}

import {
  ConflictException,
  NotFoundException,
  UnprocessableEntityException,
} from '@nestjs/common';
import { Test } from '@nestjs/testing';
import { getRepositoryToken } from '@nestjs/typeorm';
import { DataSource } from 'typeorm';
import { currentISOWeek } from '../common/iso-week';
import { Question, QuestionType } from '../entities/question.entity';
import { ResponseAnswer } from '../entities/response-answer.entity';
import { Response } from '../entities/response.entity';
import { Survey } from '../entities/survey.entity';
import type { SubmitResponseDto } from './dto/submit-response.dto';
import { SurveysService } from './surveys.service';

// ─── Fixtures ────────────────────────────────────────────────────────────────

const ORG_A = 'aaaaaaaa-0000-0000-0000-000000000001';
const ORG_B = 'aaaaaaaa-0000-0000-0000-000000000002';
const SURVEY_ID = 'cccccccc-0000-0000-0000-000000000001';
const USER_ID = 'bbbbbbbb-0000-0000-0000-000000000002';

const Q_RATING: Question = {
  id: 'dddddddd-0000-0000-0000-000000000001',
  surveyId: SURVEY_ID,
  text: 'How energised?',
  type: QuestionType.RATING,
  orderIndex: 0,
  survey: null as never,
  answers: [],
};

const Q_YESNO: Question = {
  id: 'dddddddd-0000-0000-0000-000000000002',
  surveyId: SURVEY_ID,
  text: '1:1 this week?',
  type: QuestionType.YES_NO,
  orderIndex: 1,
  survey: null as never,
  answers: [],
};

const SURVEY: Survey = {
  id: SURVEY_ID,
  organizationId: ORG_A,
  title: 'Acme Weekly Pulse',
  createdAt: new Date('2026-09-20T10:00:00Z'),
  organization: null as never,
  questions: [Q_RATING, Q_YESNO],
  responses: [],
};

const VALID_DTO: SubmitResponseDto = {
  answers: [
    { questionId: Q_RATING.id, ratingValue: 4 },
    { questionId: Q_YESNO.id, yesNoValue: true },
  ],
};

const SAVED_RESPONSE: Response = {
  id: 'eeeeeeee-0000-0000-0000-000000000001',
  surveyId: SURVEY_ID,
  userId: USER_ID,
  weekKey: currentISOWeek(),
  createdAt: new Date(),
  survey: null as never,
  user: null as never,
  answers: [],
};

// ─── Suite ───────────────────────────────────────────────────────────────────

describe('SurveysService — submitResponse', () => {
  let service: SurveysService;

  const surveyRepo = { findOne: jest.fn() };
  const questionRepo = {};
  const responseRepo = { findOne: jest.fn() };

  // Minimal transaction mock: runs the callback with a mock entity manager
  const mockManager = {
    create: jest.fn((entity: unknown, data: unknown) => data),
    save: jest.fn(),
  };
  const dataSource = {
    transaction: jest.fn((cb: (manager: typeof mockManager) => Promise<unknown>) =>
      cb(mockManager),
    ),
  };

  beforeEach(async () => {
    const module = await Test.createTestingModule({
      providers: [
        SurveysService,
        { provide: getRepositoryToken(Survey), useValue: surveyRepo },
        { provide: getRepositoryToken(Question), useValue: questionRepo },
        { provide: getRepositoryToken(Response), useValue: responseRepo },
        { provide: DataSource, useValue: dataSource },
      ],
    }).compile();

    service = module.get(SurveysService);
    jest.clearAllMocks();
  });

  // ── Happy path ─────────────────────────────────────────────────────────────

  it('returns 201 result with weekKey on a valid first submission', async () => {
    surveyRepo.findOne.mockResolvedValue(SURVEY);
    responseRepo.findOne.mockResolvedValue(null); // no prior submission
    mockManager.save
      .mockResolvedValueOnce(SAVED_RESPONSE)  // save Response
      .mockResolvedValueOnce([]);              // save ResponseAnswer[]

    const result = await service.submitResponse(SURVEY_ID, ORG_A, USER_ID, VALID_DTO);

    expect(result.id).toBe(SAVED_RESPONSE.id);
    expect(result.weekKey).toBe(SAVED_RESPONSE.weekKey);
    expect(result.surveyId).toBe(SURVEY_ID);
    expect(result.userId).toBe(USER_ID);
  });

  it('computes weekKey server-side and stores it on the response row', async () => {
    surveyRepo.findOne.mockResolvedValue(SURVEY);
    responseRepo.findOne.mockResolvedValue(null);
    mockManager.save
      .mockResolvedValueOnce(SAVED_RESPONSE)
      .mockResolvedValueOnce([]);

    await service.submitResponse(SURVEY_ID, ORG_A, USER_ID, VALID_DTO);

    const createCall = mockManager.create.mock.calls[0] as [unknown, { weekKey: string }];
    expect(createCall[1].weekKey).toMatch(/^\d{4}-W\d{2}$/);
  });

  it('persists one ResponseAnswer per question inside the transaction', async () => {
    surveyRepo.findOne.mockResolvedValue(SURVEY);
    responseRepo.findOne.mockResolvedValue(null);
    mockManager.save
      .mockResolvedValueOnce(SAVED_RESPONSE)
      .mockResolvedValueOnce([]);

    await service.submitResponse(SURVEY_ID, ORG_A, USER_ID, VALID_DTO);

    // Second save call is for the answers array
    const answersSaveCall = mockManager.save.mock.calls[1] as [unknown, unknown[]];
    expect(Array.isArray(answersSaveCall[1])).toBe(true);
    expect(answersSaveCall[1]).toHaveLength(VALID_DTO.answers.length);
  });

  // ── 404 — cross-org isolation ──────────────────────────────────────────────

  it('throws 404 when the survey belongs to a different org (cross-org submission blocked)', async () => {
    // Survey exists in ORG_A; caller is ORG_B → repo returns null (where clause includes orgId)
    surveyRepo.findOne.mockResolvedValue(null);

    await expect(
      service.submitResponse(SURVEY_ID, ORG_B, USER_ID, VALID_DTO),
    ).rejects.toThrow(NotFoundException);
  });

  it('throws 404 (not 403) on cross-org access to avoid leaking existence', async () => {
    surveyRepo.findOne.mockResolvedValue(null);

    const err = await service
      .submitResponse(SURVEY_ID, ORG_B, USER_ID, VALID_DTO)
      .catch((e) => e);

    expect(err).toBeInstanceOf(NotFoundException);
    expect(err.getStatus()).toBe(404);
  });

  // ── 409 — duplicate submission ────────────────────────────────────────────

  it('throws 409 when the member has already submitted this week (service-layer check)', async () => {
    surveyRepo.findOne.mockResolvedValue(SURVEY);
    responseRepo.findOne.mockResolvedValue({ id: 'existing-id' }); // already submitted

    await expect(
      service.submitResponse(SURVEY_ID, ORG_A, USER_ID, VALID_DTO),
    ).rejects.toThrow(ConflictException);
  });

  it('throws 409 with the correct message on duplicate submission', async () => {
    surveyRepo.findOne.mockResolvedValue(SURVEY);
    responseRepo.findOne.mockResolvedValue({ id: 'existing-id' });

    const err = await service
      .submitResponse(SURVEY_ID, ORG_A, USER_ID, VALID_DTO)
      .catch((e) => e);

    expect(err.message).toMatch(/already submitted/i);
  });

  it('throws 409 when the DB unique constraint fires (pg error code 23505)', async () => {
    surveyRepo.findOne.mockResolvedValue(SURVEY);
    responseRepo.findOne.mockResolvedValue(null);
    // Simulate transaction throwing a pg unique violation
    dataSource.transaction.mockRejectedValueOnce({ code: '23505' });

    await expect(
      service.submitResponse(SURVEY_ID, ORG_A, USER_ID, VALID_DTO),
    ).rejects.toThrow(ConflictException);
  });

  // ── 422 — answer validation ───────────────────────────────────────────────

  it('throws 422 when an answer references a questionId not in the survey', async () => {
    surveyRepo.findOne.mockResolvedValue(SURVEY);
    responseRepo.findOne.mockResolvedValue(null);

    const dto: SubmitResponseDto = {
      answers: [
        { questionId: 'unknown-question-id', ratingValue: 3 },
        { questionId: Q_YESNO.id, yesNoValue: false },
      ],
    };

    await expect(
      service.submitResponse(SURVEY_ID, ORG_A, USER_ID, dto),
    ).rejects.toThrow(UnprocessableEntityException);
  });

  it('throws 422 when a survey question has no corresponding answer', async () => {
    surveyRepo.findOne.mockResolvedValue(SURVEY);
    responseRepo.findOne.mockResolvedValue(null);

    // Only answering one of the two required questions
    const dto: SubmitResponseDto = {
      answers: [{ questionId: Q_RATING.id, ratingValue: 3 }],
    };

    await expect(
      service.submitResponse(SURVEY_ID, ORG_A, USER_ID, dto),
    ).rejects.toThrow(UnprocessableEntityException);
  });

  it('throws 422 when a RATING question receives yesNoValue instead of ratingValue', async () => {
    surveyRepo.findOne.mockResolvedValue(SURVEY);
    responseRepo.findOne.mockResolvedValue(null);

    const dto: SubmitResponseDto = {
      answers: [
        { questionId: Q_RATING.id, yesNoValue: true }, // wrong type for RATING
        { questionId: Q_YESNO.id, yesNoValue: false },
      ],
    };

    await expect(
      service.submitResponse(SURVEY_ID, ORG_A, USER_ID, dto),
    ).rejects.toThrow(UnprocessableEntityException);
  });

  it('throws 422 when a YES_NO question receives ratingValue instead of yesNoValue', async () => {
    surveyRepo.findOne.mockResolvedValue(SURVEY);
    responseRepo.findOne.mockResolvedValue(null);

    const dto: SubmitResponseDto = {
      answers: [
        { questionId: Q_RATING.id, ratingValue: 4 },
        { questionId: Q_YESNO.id, ratingValue: 2 }, // wrong type for YES_NO
      ],
    };

    await expect(
      service.submitResponse(SURVEY_ID, ORG_A, USER_ID, dto),
    ).rejects.toThrow(UnprocessableEntityException);
  });
});

// ─── ISO week helper tests ────────────────────────────────────────────────────

describe('currentISOWeek', () => {
  it('returns a string matching YYYY-Www format', () => {
    expect(currentISOWeek()).toMatch(/^\d{4}-W\d{2}$/);
  });

  it('returns 2026-W38 for 2026-09-20 (a Sunday in W38)', () => {
    expect(currentISOWeek(new Date('2026-09-20'))).toBe('2026-W38');
  });

  it('returns 2026-W38 for 2026-09-15 (the Monday that opens W38)', () => {
    expect(currentISOWeek(new Date('2026-09-15'))).toBe('2026-W38');
  });

  it('returns 2026-W37 for 2026-09-14 (the Sunday that closes W37)', () => {
    expect(currentISOWeek(new Date('2026-09-14'))).toBe('2026-W37');
  });
});

