/** A seeded user as returned by GET /auth/users */
export interface UserListItem {
  id: string;
  name: string;
  email: string;
  role: 'MANAGER' | 'MEMBER';
  organizationId: string;
  organizationName: string;
}

/** The authenticated caller as returned by GET /auth/me */
export interface CurrentUser {
  id: string;
  name: string;
  role: 'MANAGER' | 'MEMBER';
  organizationId: string;
  organizationName?: string;
}

/** A single survey question */
export interface Question {
  id: string;
  text: string;
  type: 'RATING' | 'YES_NO';
  orderIndex: number;
}

/** The active survey as returned by GET /surveys/active */
export interface ActiveSurvey {
  id: string;
  title: string;
  questions: Question[];
}

/** One answer in a response submission */
export interface AnswerPayload {
  questionId: string;
  ratingValue?: number;
  yesNoValue?: boolean;
}

/** The result of a successful response submission */
export interface SubmitResult {
  id: string;
  surveyId: string;
  userId: string;
  weekKey: string;
  createdAt: string;
}

/**
 * Minimal API client.
 *
 * All requests go through the Vite proxy: /api/* → http://localhost:3000/*
 * The X-User-Id header is set on every authenticated call.
 * There is no JWT — this is the deliberate local-auth strategy documented in SPEC.md §5.
 */

import type {
  ActiveSurvey,
  AnswerPayload,
  CurrentUser,
  SubmitResult,
  UserListItem,
} from './types';

/** The currently selected user id, written at login and read on every request. */
let currentUserId: string | null = null;

export function setCurrentUserId(id: string | null): void {
  currentUserId = id;
}

// ─── Error type ──────────────────────────────────────────────────────────────

export class ApiError extends Error {
  constructor(
    public readonly status: number,
    message: string,
  ) {
    super(message);
    this.name = 'ApiError';
  }
}

// ─── Core fetch wrapper ───────────────────────────────────────────────────────

async function apiFetch<T>(
  path: string,
  options: RequestInit = {},
): Promise<T> {
  const headers: Record<string, string> = {
    'Content-Type': 'application/json',
    ...(options.headers as Record<string, string> | undefined),
  };

  if (currentUserId) {
    headers['x-user-id'] = currentUserId;
  }

  const response = await fetch(`/api${path}`, { ...options, headers });

  if (!response.ok) {
    let message = `HTTP ${response.status}`;
    try {
      const body = (await response.json()) as { message?: string | string[] };
      if (body.message) {
        message = Array.isArray(body.message)
          ? body.message.join('; ')
          : body.message;
      }
    } catch {
      // body wasn't JSON — use the default message
    }
    throw new ApiError(response.status, message);
  }

  // 204 No Content has no body
  if (response.status === 204) {
    return undefined as unknown as T;
  }

  return response.json() as Promise<T>;
}

// ─── Endpoints ────────────────────────────────────────────────────────────────

/** GET /auth/users — no auth required */
export function getUsers(): Promise<UserListItem[]> {
  return apiFetch<UserListItem[]>('/auth/users');
}

/** GET /auth/me — requires X-User-Id */
export function getMe(): Promise<CurrentUser> {
  return apiFetch<CurrentUser>('/auth/me');
}

/** GET /surveys/active — requires X-User-Id */
export function getActiveSurvey(): Promise<ActiveSurvey> {
  return apiFetch<ActiveSurvey>('/surveys/active');
}

/** POST /surveys/:id/responses — requires X-User-Id, MEMBER only */
export function submitResponse(
  surveyId: string,
  answers: AnswerPayload[],
): Promise<SubmitResult> {
  return apiFetch<SubmitResult>(`/surveys/${surveyId}/responses`, {
    method: 'POST',
    body: JSON.stringify({ answers }),
  });
}

import React, { useEffect, useState } from 'react';
import { getUsers } from './api';
import type { UserListItem } from './types';

interface Props {
  onSelect: (user: UserListItem | null) => void;
}

/**
 * Always-visible dropdown that lists all seeded users.
 * Selecting a user triggers onSelect, which the parent uses to:
 *   - set the X-User-Id header via setCurrentUserId()
 *   - fetch /auth/me and route to the correct screen
 */
export function UserSelector({ onSelect }: Props): React.JSX.Element {
  const [users, setUsers] = useState<UserListItem[]>([]);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [selectedId, setSelectedId] = useState<string>('');

  useEffect(() => {
    getUsers()
      .then(setUsers)
      .catch((err: unknown) => {
        setLoadError(err instanceof Error ? err.message : 'Failed to load users');
      });
  }, []);

  function handleChange(e: React.ChangeEvent<HTMLSelectElement>): void {
    const id = e.target.value;
    setSelectedId(id);
    if (!id) {
      onSelect(null);
      return;
    }
    const user = users.find((u) => u.id === id) ?? null;
    onSelect(user);
  }

  if (loadError) {
    return (
      <div style={styles.bar}>
        <strong>Pulse Surveys</strong>
        <span style={{ color: '#c00' }}>Could not load users: {loadError}</span>
      </div>
    );
  }

  return (
    <div style={styles.bar}>
      <strong>Pulse Surveys</strong>
      <label htmlFor="user-select" style={{ marginLeft: 16 }}>
        Logged in as:&nbsp;
      </label>
      <select
        id="user-select"
        value={selectedId}
        onChange={handleChange}
        style={styles.select}
      >
        <option value="">— select a user —</option>
        {users.map((u) => (
          <option key={u.id} value={u.id}>
            {u.name} ({u.organizationName} · {u.role})
          </option>
        ))}
      </select>
    </div>
  );
}

const styles: Record<string, React.CSSProperties> = {
  bar: {
    display: 'flex',
    alignItems: 'center',
    padding: '10px 16px',
    background: '#1a1a2e',
    color: '#fff',
    gap: 8,
  },
  select: {
    padding: '4px 8px',
    fontSize: 14,
    borderRadius: 4,
    border: '1px solid #555',
    background: '#fff',
    color: '#000',
    cursor: 'pointer',
  },
};

import React, { useCallback, useEffect, useState } from 'react';
import { ApiError, getActiveSurvey, submitResponse } from './api';
import type { ActiveSurvey, AnswerPayload } from './types';

/**
 * Member survey submission screen.
 *
 * Flow:
 *   1. On mount: fetch GET /surveys/active.
 *   2. Render each question with appropriate input controls.
 *   3. Submit button is disabled until every question has an answer.
 *   4. On POST success (201): show confirmation and freeze the form.
 *   5. On 409: show "already submitted" message.
 *   6. On other errors: show the error message.
 */
export function MemberScreen(): React.JSX.Element {
  const [survey, setSurvey] = useState<ActiveSurvey | null>(null);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  // Map from questionId → chosen answer value
  const [answers, setAnswers] = useState<Map<string, number | boolean>>(new Map());

  const [submitting, setSubmitting] = useState(false);
  const [submitStatus, setSubmitStatus] = useState<'idle' | 'success' | 'error'>('idle');
  const [submitMessage, setSubmitMessage] = useState<string>('');

  useEffect(() => {
    setLoading(true);
    setLoadError(null);
    getActiveSurvey()
      .then((s) => {
        setSurvey(s);
        setAnswers(new Map());
        setSubmitStatus('idle');
        setSubmitMessage('');
      })
      .catch((err: unknown) => {
        setLoadError(err instanceof Error ? err.message : 'Failed to load survey');
      })
      .finally(() => setLoading(false));
  }, []);

  const setAnswer = useCallback(
    (questionId: string, value: number | boolean) => {
      setAnswers((prev) => new Map(prev).set(questionId, value));
    },
    [],
  );

  const allAnswered =
    survey !== null && survey.questions.every((q) => answers.has(q.id));

  async function handleSubmit(e: React.FormEvent): Promise<void> {
    e.preventDefault();
    if (!survey || !allAnswered || submitting) return;

    setSubmitting(true);
    setSubmitStatus('idle');
    setSubmitMessage('');

    const payload: AnswerPayload[] = survey.questions.map((q) => {
      const val = answers.get(q.id);
      if (q.type === 'RATING') {
        return { questionId: q.id, ratingValue: val as number };
      } else {
        return { questionId: q.id, yesNoValue: val as boolean };
      }
    });

    try {
      await submitResponse(survey.id, payload);
      setSubmitStatus('success');
      setSubmitMessage('Response submitted successfully.');
    } catch (err: unknown) {
      setSubmitStatus('error');
      if (err instanceof ApiError && err.status === 409) {
        setSubmitMessage('You have already submitted this week.');
      } else {
        setSubmitMessage(err instanceof Error ? err.message : 'Submission failed.');
      }
    } finally {
      setSubmitting(false);
    }
  }

  if (loading) {
    return <p style={styles.info}>Loading survey…</p>;
  }

  if (loadError) {
    return <p style={styles.error}>Error: {loadError}</p>;
  }

  if (!survey) {
    return <p style={styles.info}>No active survey found for your organization.</p>;
  }

  const formDisabled = submitStatus === 'success' || submitting;

  return (
    <div style={styles.container}>
      <h2 style={styles.title}>{survey.title}</h2>

      <form onSubmit={(e) => void handleSubmit(e)}>
        {survey.questions.map((q, idx) => (
          <div key={q.id} style={styles.questionBlock}>
            <p style={styles.questionText}>
              {idx + 1}. {q.text}
            </p>

            {q.type === 'RATING' && (
              <div style={styles.buttonRow}>
                {([1, 2, 3, 4, 5] as const).map((n) => (
                  <button
                    key={n}
                    type="button"
                    disabled={formDisabled}
                    onClick={() => setAnswer(q.id, n)}
                    style={{
                      ...styles.answerBtn,
                      ...(answers.get(q.id) === n ? styles.answerBtnSelected : {}),
                    }}
                    aria-pressed={answers.get(q.id) === n}
                  >
                    {n}
                  </button>
                ))}
              </div>
            )}

            {q.type === 'YES_NO' && (
              <div style={styles.buttonRow}>
                {([true, false] as const).map((val) => (
                  <button
                    key={String(val)}
                    type="button"
                    disabled={formDisabled}
                    onClick={() => setAnswer(q.id, val)}
                    style={{
                      ...styles.answerBtn,
                      ...(answers.get(q.id) === val ? styles.answerBtnSelected : {}),
                    }}
                    aria-pressed={answers.get(q.id) === val}
                  >
                    {val ? 'Yes' : 'No'}
                  </button>
                ))}
              </div>
            )}
          </div>
        ))}

        <button
          type="submit"
          disabled={!allAnswered || formDisabled}
          style={{
            ...styles.submitBtn,
            ...(!allAnswered || formDisabled ? styles.submitBtnDisabled : {}),
          }}
        >
          {submitting ? 'Submitting…' : 'Submit'}
        </button>
      </form>

      {submitStatus === 'success' && (
        <p style={styles.success}>{submitMessage}</p>
      )}
      {submitStatus === 'error' && (
        <p style={styles.error}>{submitMessage}</p>
      )}
    </div>
  );
}

const styles: Record<string, React.CSSProperties> = {
  container: {
    maxWidth: 600,
    margin: '24px auto',
    padding: '0 16px',
    fontFamily: 'sans-serif',
  },
  title: {
    marginBottom: 24,
    fontSize: 20,
    fontWeight: 600,
  },
  questionBlock: {
    marginBottom: 24,
    padding: 16,
    border: '1px solid #ddd',
