  },
  answerBtn: {
    padding: '8px 18px',
    border: '1px solid #aaa',
    borderRadius: 4,
    background: '#fff',
    cursor: 'pointer',
    fontSize: 14,
    minWidth: 44,
  },
  answerBtnSelected: {
    background: '#1a1a2e',
    color: '#fff',
