  },
  submitBtn: {
    padding: '10px 28px',
    fontSize: 15,
    fontWeight: 600,
    border: 'none',
    borderRadius: 4,
    background: '#1a1a2e',
    color: '#fff',
    cursor: 'pointer',
    marginTop: 8,
  },
  submitBtnDisabled: {
    background: '#aaa',
    cursor: 'not-allowed',
  },
  success: {
    marginTop: 16,
    color: '#197a1f',
    fontWeight: 500,
  },
  error: {
    marginTop: 16,
    color: '#c00',
    fontWeight: 500,
  },
  info: {
    padding: '24px 16px',
    color: '#555',
  },
};

