/**
 * Manager screen placeholder.
 * The summary view will be implemented in the next commit.
 */
export function ManagerScreen(): React.JSX.Element {
  return (
    <div
      style={{
        maxWidth: 600,
        margin: '24px auto',
        padding: '24px 16px',
        fontFamily: 'sans-serif',
        color: '#555',
        border: '1px dashed #ccc',
